import json, os, re

d = os.environ.get('RLM_SESSION_DIR')
with open(d + '/semantic-edges.jsonl') as f:
    data = [json.loads(line) for line in f]

# Find demographic messages
for item in data:
    if 'content' in item and isinstance(item['content'], list):
        for part in item['content']:
            if isinstance(part, dict) and 'text' in part and 'Demo' in str(part):
                print(repr(part)[:200] + "...")

# Or better, search for relevant text
print("\n--- All sequential messages ---")
for item in data:
    if 'message' in item and 'role' in item.get('message', {}):
        role = item['message'].get('role', '')
        content = item['message'].get('content', [])
        if role == 'assistant':
            for c in content:
